/**
 * browserbase-effect -- an Effect-native SDK for the Browserbase API.
 *
 * `./services` is generated by `scripts/generate.ts` from the Browserbase
 * OpenAPI spec. Everything else in this folder is hand-written and built on
 * `@distilled.cloud/core`.
 *
 * @example
 * ```ts
 * import { Effect, Layer } from "effect";
 * import { FetchHttpClient } from "effect/http";
 * import * as Browserbase from "browserbase-effect";
 *
 * const program = Effect.gen(function* () {
 *   const session = yield* Browserbase.createSession({ projectId: "..." });
 *   return session.connectUrl;
 * });
 *
 * program.pipe(
 *   Effect.provide(Layer.mergeAll(FetchHttpClient.layer, Browserbase.CredentialsFromEnv)),
 *   Effect.runPromise,
 * );
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as Category from "./category.ts";
export * as T from "./traits.ts";
export {
  BrowserbaseProtocol,
  type BrowserbaseOpError,
  type BrowserbaseOpContext,
} from "./protocol.ts";
export { paginateCursor, paginateOffset, paginateSince } from "./pagination.ts";
export * as Retry from "./retry.ts";
export * from "./operations.ts";
